<?php
require_once __DIR__.'/includes/module.php';
require_roles(['admin','staff']);
$page_title='Presensi Peserta';
$training_id=(int)($_GET['training_id']??0);
$trainings=module_list($pdo,'SELECT id,code,title FROM trainings ORDER BY start_date DESC');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$training_id=(int)$_POST['training_id'];$date=$_POST['attendance_date']??date('Y-m-d');foreach(($_POST['attendance']??[]) as $reg_id=>$status){$s=$pdo->prepare('INSERT INTO attendance(registration_id,attendance_date,status,notes) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),notes=VALUES(notes)');$s->execute([(int)$reg_id,$date,$status,trim($_POST['note'][$reg_id]??'')]);}flash('Presensi berhasil disimpan.');header('Location: attendance.php?training_id='.$training_id);exit;}
$rows=[];if($training_id){$s=$pdo->prepare("SELECT r.id AS registration_id,p.name,p.institution,a.status,a.notes FROM registrations r JOIN participants p ON p.id=r.participant_id LEFT JOIN attendance a ON a.registration_id=r.id AND a.attendance_date=? WHERE r.training_id=? AND r.status IN ('Terdaftar','Terverifikasi') ORDER BY p.name");$s->execute([$_GET['date']??date('Y-m-d'),$training_id]);$rows=$s->fetchAll();}
require __DIR__.'/includes/header.php';show_flash();?>
<section class="panel"><form class="searchbar" method="get"><select name="training_id" required><option value="">Pilih kegiatan pelatihan</option><?php foreach($trainings as $t):?><option value="<?=$t['id']?>" <?=$training_id===$t['id']?'selected':''?>><?=e($t['code'].' — '.$t['title'])?></option><?php endforeach;?></select><input type="date" name="date" value="<?=e($_GET['date']??date('Y-m-d'))?>"><button class="btn">Tampilkan</button></form>
<?php if($training_id):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="training_id" value="<?=$training_id?>"><div class="field" style="max-width:240px;margin-bottom:14px"><label>Tanggal Presensi</label><input type="date" name="attendance_date" value="<?=e($_GET['date']??date('Y-m-d'))?>" required></div><table><thead><tr><th>Nama Peserta</th><th>Instansi</th><th>Status Kehadiran</th><th>Catatan</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="4" class="empty">Belum ada peserta terdaftar pada kegiatan ini.</td></tr><?php endif;foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['institution'])?></td><td><select name="attendance[<?=$r['registration_id']?>]"><?php foreach(['Hadir','Izin','Sakit','Alpa'] as $st):?><option <?=$r['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></td><td><input name="note[<?=$r['registration_id']?>]" value="<?=e($r['notes'])?>"></td></tr><?php endforeach;?></tbody></table><div class="form-actions"><button class="btn">Simpan Presensi</button></div></form><?php else:?><div class="empty">Pilih kegiatan dan tanggal untuk mengelola presensi.</div><?php endif;?></section>
<?php require __DIR__.'/includes/footer.php';?>
